/* ---------- cofactor reference: food sources + why it matters, no dose amounts ----------
   Deliberately no mg/IU figures — the right amount depends on bloodwork and a doctor. */
/* ---------- food colour coding ----------
   Each food source gets tinted by what it is, so a nutrient's sources read at
   a glance: greens for vegetables, red for meat, blue for fish, and so on. */
const FOODC={
  /* minerals and herbs are checked first: foodKind returns the first match, and
     "potassium (avocado, potato)" should read as a mineral, not a vegetable */
  mineral:{n:"Minerals, salts",c:"#8a5fc9", w:["salt","sodium","potassium","magnesium","zinc","selenium","iodine","calcium","electrolyte","mineral","copper"]},
  herb:  {n:"Herbs, tea",  c:"#2f9e8f", w:["tea","chamomile","herb","turmeric","ginger","mint","matcha","coffee","parsley"]},
  veg:   {n:"Vegetables", c:"#3f9e54", w:["spinach","broccoli","cabbage","bell pepper","kale","leafy greens","greens","vegetable","asparagus","brussels","avocado","beet","celery","veg","potato","onion","garlic","cauliflower","carrot","mushroom","squash","pepper"]},
  meat:  {n:"Meat",       c:"#cf4b3c", w:["beef","red meat","chicken","liver","organ meat","meat","poultry","turkey","pork","lamb","broth","gelatin","collagen"]},
  fish:  {n:"Fish",       c:"#3b7fd1", w:["fish","salmon","sardines","mackerel","oysters","clams","seafood","tuna","shellfish","anchov"]},
  fruit: {n:"Fruit",      c:"#e07b2a", w:["citrus","kiwi","berries","fruit","banana","orange","apple","tomato"]},
  nut:   {n:"Nuts, seeds",c:"#9a6f42", w:["seeds","almonds","cashews","nuts","walnuts","peanut","sesame","chia","flax","chocolate","cocoa","sunflower","hemp"]},
  dairy: {n:"Eggs, dairy",c:"#c9a13a", w:["egg","yogurt","whey","dairy","cheese","milk","kefir"]},
  grain: {n:"Grains, legumes",c:"#8d8f3a", w:["lentils","legumes","grains","beans","oats","quinoa","rice","chickpea"]},
  other: {n:"Other",      c:"#c96f8f", w:[]}
};
function foodKind(item){
  const t=item.toLowerCase();
  for(const k in FOODC){if(FOODC[k].w.some(w=>t.includes(w)))return k;}
  return "other";
}
/* split on commas that sit outside brackets, so "potassium (avocado, potato)"
   stays one item instead of breaking in half */
function splitFoods(str){
  const out=[];let buf="",depth=0;
  for(const ch of String(str)){
    if(ch==="(")depth++;
    else if(ch===")")depth=Math.max(0,depth-1);
    if(ch===","&&depth===0){out.push(buf);buf="";continue;}
    buf+=ch;
  }
  out.push(buf);
  return out.map(x=>x.trim()).filter(Boolean);
}
/* split a nutrient's source string into individually tinted chips */
function foodChips(str){
  if(!str)return "";
  const parts=splitFoods(str);
  return `<div class="foods">${parts.map(p=>{
    const k=foodKind(p),c=FOODC[k].c;
    const plain=/^\(/.test(p);   // parenthetical notes aren't foods
    return plain
      ? `<span class="foodnote">${p}</span>`
      : `<span class="food1" style="--fc:${c}"><i></i>${p}</span>`;
  }).join("")}</div>`;
}
