 src:[{n:"Hormone effects in healthy elderly men",u:"https://pubmed.ncbi.nlm.nih.gov/15080785/"},{n:"Raloxifene vs tamoxifen in pubertal gynecomastia",u:"https://www.sciencedirect.com/science/article/abs/pii/S0022347604003191"},{n:"SERMs and bone health in men (review)",u:"https://www.tandfonline.com/doi/full/10.1080/13685538.2018.1448058"}]
