function mk(id,name,cat,dose,unit,sched,vial,rem,timing,flag){
  return{id,name,cat,dose,unit,sched,vialMg:vial,remaining:rem,bacMl:2,mixDate:iso(new Date()),
    time:/night|bed|evening|pm/i.test(timing)?"pm":"am",clock:"",
    timing,label:flag===true?"1 pin (~4mg blend)":null,status:flag==="off"?"off":"active"};
}
