/* the proper name and the names people actually use — a forum post says
   GLP-3, a trial paper says LY3437943, a box says Zepbound. All of them
   should find the same card. */
const ALIAS={"retatrutide": ["LY3437943", "GLP-3", "Reta", "triple G"], "tirzepatide": ["Mounjaro", "Zepbound", "LY3298176", "Tirz"], "semaglutide": ["Ozempic", "Wegovy", "Rybelsus", "Sema"], "cagrilintide": ["AM833", "Cagri"], "cagrisema": ["CagriSema", "cagrilintide + semaglutide"], "tesamorelin": ["Egrifta", "TH9507", "Tesa", "Egrifta SV"], "sermorelin": ["Geref", "GRF (1-29)", "GHRH (1-29)", "GRF 1-29"], "ipamorelin": ["NNC 26-0161", "Ipa"], "cjc1295nodac": ["Modified GRF (1-29)", "Mod GRF", "CJC-1295 without DAC", "Mod GRF 1-29"], "tesaipacjc1033": ["Tesamorelin + Ipamorelin + CJC-1295", "Tesa Ipa CJC blend", "10/3/3 blend"], "ss31": ["Elamipretide", "Forzinity", "MTP-131", "Bendavia"], "motsc": ["Mitochondrial ORF of the 12S rRNA type-c", "MOTS-c"], "nad": ["Nicotinamide adenine dinucleotide", "NAD+", "NAD"], "5amino1mq": ["5-amino-1-methylquinolinium", "5A1MQ", "NNMT inhibitor"], "bpc157": ["Body Protection Compound 157", "Pentadecapeptide BPC 157", "PL 14736", "BPC"], "tb500": ["Thymosin Beta-4 fragment", "TB4", "Tb-500", "Thymosin Beta-4", "TB 500"], "ghkcu": ["Copper tripeptide-1", "Gly-His-Lys-Cu", "GHK copper", "Cu-GHK"], "ahkcu": ["Ala-His-Lys-Cu", "AHK copper peptide"], "kpv": ["Lys-Pro-Val", "alpha-MSH (11-13)", "Lysine-proline-valine", "alpha-MSH 11-13"], "glutathione": ["GSH", "L-glutathione", "gamma-glutamyl-cysteinyl-glycine"], "thymosinalpha1": ["Zadaxin", "Thymalfasin", "Talpha1", "TA-1", "Ta1"], "epithalon": ["Epitalon", "AEDG", "Ala-Glu-Asp-Gly", "Epithalamin (the extract)", "Epithalamin"], "pinealon": ["EDR", "Glu-Asp-Arg", "EDR peptide", "Pinealon"], "dsip": ["Delta Sleep-Inducing Peptide"], "ara290": ["Cibinetide", "ARA290", "EPO helix-B peptide", "ARA 290"], "kisspeptin10": ["KP-10", "Metastin (1-54) fragment", "Kiss1", "Metastin"], "lcarnitine": ["Levocarnitine", "L-carnitine L-tartrate", "LCLT", "Carnitor", "L-carnitine tartrate"], "aod9604": ["hGH fragment 176-191", "AOD", "AOD9604"], "pt141": ["Bremelanotide", "Vyleesi", "PT141", "PT 141"], "mt2": ["Melanotan II", "MT-II"], "selank": ["TP-7", "tuftsin analogue", "Selanc"], "semax": ["ACTH (4-10) analogue", "Met-Glu-His-Phe-Pro-Gly-Pro", "ACTH 4-10 analogue", "Semaks"], "dihexa": ["N-hexanoic-Tyr-Ile-(6) aminohexanoic amide", "PNB-0408"], "cerebrolysin": ["FPF-1070", "Cere", "Cerebrolysin", "FPF 1070"], "melatonin": ["N-acetyl-5-methoxytryptamine", "Circadin", "Slenyto"], "ace031": ["Ramatercept", "ActRIIB-Fc", "soluble activin receptor IIB", "ACE 031"], "adipotide": ["FTPP", "prohibitin-targeting peptidomimetic", "Prohibitin-targeting peptide-1"], "epo": ["Erythropoietin", "Epoetin alfa", "Procrit", "Epogen", "Aranesp", "Retacrit", "Darbepoetin"], "thymalin": ["Thymus polypeptide extract", "Thymalinum", "Thymus extract", "Timalin"], "klow": ["KPV + Larazotide + GHK-Cu + BPC-157/TB-500"], "glow": ["GHK-Cu + BPC-157 + TB-500"], "wolverine": ["BPC-157 + TB-500"], "bpc157tb500": ["Wolverine blend", "BPC-157 + TB-500"], "vip": ["Vasoactive Intestinal Peptide"], "larazotide": ["Larazotide acetate", "AT-1001", "INN-202"], "hexarelin": ["Examorelin", "EP-23905"], "ghrp2": ["Pralmorelin", "GHRP-2"], "ghrp6": ["GHRP-6", "growth hormone releasing peptide 6"], "hcg": ["Human chorionic gonadotropin", "Pregnyl", "Ovidrel", "Novarel"], "bacwater": ["Bacteriostatic water", "0.9% benzyl alcohol water"], "aceticacid": ["Acetic acid", "dilute acetic acid diluent"], "testosteronecypionate": ["Depo-Testosterone", "Test C", "Test Cyp", "Testosterone"], "testosteroneenanthate": ["Delatestryl", "Xyosted", "Test E"], "testosteronepropionate": ["Testoviron", "Test P"], "testosteroneundecanoate": ["Aveed", "Nebido", "Jatenzo"], "sustanon": ["Sustanon 250", "Omnadren", "Test blend"], "nandrolonedecanoate": ["Deca-Durabolin", "Deca"], "nandrolonephenylpropionate": ["Durabolin", "NPP"], "trenboloneacetate": ["Finaplix", "Tren A", "Trenbolone", "Tren", "Tren Ace"], "trenboloneenanthate": ["Tren E"], "drostanolone": ["Masteron", "Drolban"], "methenolone": ["Primobolan", "Primo", "Nibal"], "boldenone": ["Equipoise", "EQ", "Boldenone undecylenate"], "oxandrolone": ["Anavar", "Oxandrin", "Var"], "stanozolol": ["Winstrol", "Winny", "Stromba"], "methandrostenolone": ["Dianabol", "Dbol", "Averbol", "Methandienone"], "oxymetholone": ["Anadrol", "Anapolon"], "turinabol": ["Oral Turinabol", "Tbol", "Chlorodehydromethyltestosterone"], "superdrol": ["Methasterone", "Sdrol"], "fluoxymesterone": ["Halotestin", "Halo"], "anastrozole": ["Arimidex", "Arimidex AI"], "exemestane": ["Aromasin"], "letrozole": ["Femara"], "tamoxifen": ["Nolvadex", "Soltamox"], "clomiphene": ["Clomid", "Serophene"], "enclomiphene": ["Androxal", "Enclomiphene citrate"], "hmg": ["Menopur", "Human menopausal gonadotropin"], "cabergoline": ["Dostinex", "Caber"], "raloxifene": ["Evista"], "testcyp": ["Depo-Testosterone", "Testosterone cypionate", "Test C"], "testc": ["Depo-Testosterone", "Testosterone cypionate"], "test": ["Testosterone", "Test Cyp", "Test E"], "dianabol": ["Dbol", "D-bol", "Methandrostenolone", "Methandienone", "Averbol"], "trenacetate": ["Trenbolone", "Tren", "Tren Ace"]};
function pepAlias(p){return ALIAS[pepKey(p&&p.name)]||[];}
/* does this peptide answer to the typed text, by name or by any alias? */
function pepMatches(name,q){
  q=String(q||"").toLowerCase().replace(/[^a-z0-9]/g,"");
  if(!q)return true;
  if(pepKey(name).includes(q))return true;
  return (ALIAS[pepKey(name)]||[]).some(a=>a.toLowerCase().replace(/[^a-z0-9]/g,"").includes(q));
}
/* fall back on the peptide's own category label when the name is unknown */
const CATFAM={"glp-1":"glp","gh axis":"gh",mitochondria:"mito",metabolic:"metabolic",recovery:"regen",
  nerve:"regen",detox:"antiox",immune:"immune",longevity:"pineal",sleep:"sleep",hormone:"gh","fat-ox":"metabolic",
  "fat loss":"metabolic",nootropic:"neuro",cognitive:"neuro",tanning:"melano","anti-inflam":"immune",
  "recovery/skin":"regen",skin:"copper",gut:"gut",muscle:"muscle",blood:"blood",supply:"supply",
  peptide:"regen",other:"regen",gear:"gear",anabolic:"gear",steroid:"gear",aas:"gear",
  ancillary:"gear","pct":"gear"};
/* PMAP keys sorted longest first, so the most specific prefix wins */
const PMAPK=Object.keys(typeof PMAP!=="undefined"?PMAP:{}).sort((a,b)=>b.length-a.length);
function pepKey(name){return String(name||"").toLowerCase().replace(/[^a-z0-9]/g,"");}
function pepFams(p){
  if(p&&Array.isArray(p.fams)&&p.fams.length)return p.fams;
  const k=pepKey(p&&p.name);
  if(PMAP[k])return PMAP[k];
  // "Tren Ace" and "Test C" should land where "tren" and "testcyp" land, so
  // fall back to the longest mapped key the typed name begins with
  if(k.length>=2){
    const hit=PMAPK.find(x=>x.length>=2&&k.startsWith(x));
    if(hit)return PMAP[hit];
  }
  return [CATFAM[String(p&&p.cat||"").toLowerCase()]||"other"];
}
/* oil-based compounds are not reconstituted, they come at a concentration */
function isGear(p){return pepFams(p).indexOf("gear")>=0;}
function pepColors(p){
  const k=pepKey(p&&p.name),fams=pepFams(p);
  if(fams.length===1&&PSHADE[k])return[PSHADE[k]];
  return fams.map(f=>(PFAM[f]||PFAM.other).c);
}
/* one flat colour, or hard-edged stripes for a blend */
function pepPaint(p){
  const c=pepColors(p);
  if(c.length===1)return c[0];
  const n=c.length;
  return "linear-gradient(100deg,"+c.map((x,i)=>
    `${x} ${(i/n*100).toFixed(2)}% ${((i+1)/n*100).toFixed(2)}%`).join(",")+")";
}
function pepFamNames(p){
  return [...new Set(pepFams(p))].map(f=>(PFAM[f]||PFAM.other).n).join(" + ");
}
/* the named colour box used everywhere a dose is shown */
function pepBox(p,opts){
  const o=opts||{};
  const n=pepColors(p).length;
  return `<span class="pepbox${o.done?" done":""}${o.sm?" sm":""}" style="background:${pepPaint(p)}"
    title="${pepFamNames(p)}"${o.attr||""}><span class="pbn">${p.name}</span>${
    n>1?`<span class="pbn2">${n}</span>`:""}${o.done?`<span class="pbck">✓</span>`:""}</span>`;
}

/* ---------- state ---------- */
const KEY="vialback_v2";
let S=load();
function load(){
  let v={};try{v=JSON.parse(localStorage.getItem(KEY))||{};}catch(e){}
  return{
    track:v.track||(window.VIALBACK_PUBLIC?[]:DEF.map(p=>({...p}))),
    archive:v.archive||[],
    workouts:v.workouts||[],meals:v.meals||[],
    macros:v.macros||{kcal:2200,protein:180,carbs:200,fat:70},
    log:v.log||{},sales:v.sales||[],resale:v.resale||[],weights:v.weights||[],
    // vial lifecycle: a new vial opened ("buy") and a vial running dry ("empty")
    events:v.events||[],
    // bloodwork: {marker:[{d,v}]} plus any ranges edited to match a real report
    labs:v.labs||{},labRanges:v.labRanges||{},
    // meals you've logged once, reusable with a single tap
    foods:v.foods||[],
    settings:v.settings||{notify:true,theme:null,seenTip:false},
    // cycle and mood log, prescriptions, and the body stats behind the macro
    // calculator. Anything added to S has to be restored here or it silently
    // resets on every reload.
    cycle:v.cycle||{sex:"",periods:[],days:{}},
    meds:v.meds||[],
    body:v.body||{unit:"imp"}
  };
}
/* record a vial event against a peptide, one per peptide per day per type */
function pepEvent(p,type,date){
  const d=date||iso(new Date());
  if(S.events.some(e=>e.pep===p.id&&e.type===type&&e.date===d))return;
  S.events.push({id:Date.now()+""+Math.random().toString(36).slice(2,6),
    pep:p.id,name:p.name,type,date:d,at:Date.now()});
}

/* ---------- keeping your data ----------
   Everything here lives in one browser. Safari clears script-writable storage
   after seven days without a visit, so without this the whole log can simply
   disappear between one gym trip and the next. */
const PREVKEY=KEY+"_prev";
const IDBNAME="vialback",IDBSTORE="state";
let _idb=null,_mirrorT=null;

function idbOpen(){
  if(_idb)return Promise.resolve(_idb);
  return new Promise(res=>{
    try{
      const rq=indexedDB.open(IDBNAME,1);
      rq.onupgradeneeded=()=>{const db=rq.result;
        if(!db.objectStoreNames.contains(IDBSTORE))db.createObjectStore(IDBSTORE);};
      rq.onsuccess=()=>{_idb=rq.result;res(_idb);};
      rq.onerror=()=>res(null);
    }catch(e){res(null);}
  });
}
/* a second copy, written a moment after the last change rather than on every
   keystroke — IndexedDB is what persistent storage actually protects */
function mirror(json){
  clearTimeout(_mirrorT);
  _mirrorT=setTimeout(async()=>{
    const db=await idbOpen();if(!db)return;
    try{const tx=db.transaction(IDBSTORE,"readwrite");
      tx.objectStore(IDBSTORE).put({json,at:Date.now()},"main");}catch(e){}
  },1200);
}
async function idbRead(){
  const db=await idbOpen();if(!db)return null;
  return new Promise(res=>{
    try{const rq=db.transaction(IDBSTORE,"readonly").objectStore(IDBSTORE).get("main");
      rq.onsuccess=()=>res(rq.result||null);rq.onerror=()=>res(null);}
    catch(e){res(null);}
  });
}
/* ask the browser not to evict us. On iOS this is granted for a home-screen
   install and is the single most effective thing here. */
async function askPersist(){
  try{
    if(!navigator.storage||!navigator.storage.persist)return null;
    if(await navigator.storage.persisted())return true;
    return await navigator.storage.persist();
  }catch(e){return null;}
}
async function storageReport(){
  const out={persisted:null,usedMB:null,quotaMB:null,idbAt:null};
  try{if(navigator.storage&&navigator.storage.persisted)out.persisted=await navigator.storage.persisted();}catch(e){}
  try{if(navigator.storage&&navigator.storage.estimate){const e=await navigator.storage.estimate();
    out.usedMB=e.usage?(e.usage/1048576).toFixed(1):null;
    out.quotaMB=e.quota?(e.quota/1048576).toFixed(0):null;}}catch(e){}
  const r=await idbRead();if(r&&r.at)out.idbAt=r.at;
  return out;
}
/* how many days since the last export, null if never */
function backupAge(){
  const t=S.settings&&S.settings.lastBackup;
  return t?Math.floor((Date.now()-t)/DAY):null;
}
/* boot-time recovery: localStorage, then the previous-good copy, then IndexedDB */
async function recoverState(){
  const has=o=>o&&typeof o==="object"&&(Array.isArray(o.track)||o.log||o.workouts);
  let cur=null;
  try{cur=JSON.parse(localStorage.getItem(KEY)||"null");}catch(e){}
  if(has(cur))return null;
  let prev=null;
  try{prev=JSON.parse(localStorage.getItem(PREVKEY)||"null");}catch(e){}
  if(has(prev)){
    localStorage.setItem(KEY,JSON.stringify(prev));
    return "Recovered from the previous saved copy.";
  }
  const rec=await idbRead();
  if(rec&&rec.json){
    let d=null;try{d=JSON.parse(rec.json);}catch(e){}
    if(has(d)){
      localStorage.setItem(KEY,rec.json);
      const when=new Date(rec.at).toLocaleDateString();
      return `Recovered your data from the backup copy in this browser (saved ${when}).`;
    }
  }
  return null;
}

function save(){try{
  const json=JSON.stringify(S);
  // keep the copy we are about to replace, so a truncated write is survivable
  const cur=localStorage.getItem(KEY);
  if(cur&&cur.length>50)localStorage.setItem(PREVKEY,cur);
  localStorage.setItem(KEY,json);
  mirror(json);
  syncNative();
  updateBadge();
}catch(e){
  // out of quota is the usual cause, and silently doing nothing is how data
  // goes missing without anyone noticing
  toast("Could not save — device storage may be full");
}}
function pById(id){return S.track.find(p=>p.id===id);}
function activeTrack(){return S.track.filter(p=>p.status==="active");}


/* ---------- reminders ----------
   No server means nothing can wake the phone on a schedule. What does work
   without one is the badge: a number on the home-screen icon that survives the
   app being closed. That carries the reminder, and notifications are a single
   grouped message rather than one per peptide. */
let _sw=null;
function initSW(){
  if(!("serviceWorker" in navigator)||location.protocol==="file:")return;
  navigator.serviceWorker.register("./sw.js").then(r=>{_sw=r;}).catch(()=>{});
}
/* what is still outstanding today */
function dueToday(){
  const d=new Date(),k=iso(d),logd=S.log[k]||{};
  const due=S.track.filter(p=>p.status==="active"&&!p.label&&dueOn(p,d));
  return {due,pending:due.filter(p=>!logd[p.id])};
}
/* the count on the icon, cleared when the last dose is logged */
function updateBadge(){
  try{
    if(!navigator.setAppBadge)return;
    const n=S.settings.remind===false?0:dueToday().pending.length;
    if(n>0)navigator.setAppBadge(n);else navigator.clearAppBadge();
  }catch(e){}
}
async function askNotify(){
  try{
    if(!("Notification" in window))return "unsupported";
    if(Notification.permission==="granted")return "granted";
    if(Notification.permission==="denied")return "denied";
    return await Notification.requestPermission();
  }catch(e){return "unsupported";}
}
/* one message listing everything outstanding, not one per peptide */
function reminderText(){
  const {pending}=dueToday();
  if(!pending.length)return null;
  const am=pending.filter(p=>(p.time||"am")==="am").map(p=>p.name);
  const pm=pending.filter(p=>(p.time||"am")==="pm").map(p=>p.name);
  const parts=[];
  if(am.length)parts.push("Morning: "+am.join(", "));
  if(pm.length)parts.push("Night: "+pm.join(", "));
  return {title:`${pending.length} ${pending.length===1?"dose":"doses"} still to take`,
          body:parts.join(" · ")};
}
async function fireReminder(force){
  if(!S.settings.remind&&!force)return false;
  const t=reminderText();
  if(!t)return false;
  if(!("Notification" in window)||Notification.permission!=="granted")return false;
  const key=iso(new Date());
  if(!force&&S.settings.lastNotified===key)return false;   // once a day, not once a render
  S.settings.lastNotified=key;save();
  try{
    const reg=_sw||(navigator.serviceWorker&&await navigator.serviceWorker.ready);
    if(reg&&reg.active){reg.active.postMessage({type:"notify",title:t.title,body:t.body,tag:"vialback-due"});return true;}
    new Notification(t.title,{body:t.body,icon:"./icon-192.png",tag:"vialback-due"});
    return true;
  }catch(e){return false;}
}
/* while the app is open, check on the hour and when it comes back to the front */
function startReminderLoop(){
  const tick=()=>{
    updateBadge();
    const now=new Date();
    const hour=(S.settings.remindAt!=null?S.settings.remindAt:9);
    if(now.getHours()>=hour)fireReminder(false);
  };
  tick();
  setInterval(tick,15*60*1000);
  document.addEventListener("visibilitychange",()=>{if(!document.hidden)tick();});
}

/* push today's doses + low stock to the Android shell so it can build the
   notification that mirrors the day popup (no-op in a plain browser) */
function syncNative(){try{
  if(!(window.AndroidBridge&&AndroidBridge.syncState))return;
  const today=new Date(),key=iso(today),logd=S.log[key]||{};
  const due=S.track.filter(p=>p.status==="active"&&dueOn(p,today));
  const pending=due.filter(p=>!logd[p.id]);
  const lbl=p=>p.name+" "+doseLabel(p);
  const low=S.track.filter(p=>p.status==="active").filter(p=>{const d=daysLeft(p);return p.remaining<=0||(d!=null&&d<=7);})
    .map(p=>p.name+(p.remaining<=0?" (out)":" ("+daysLeft(p)+"d)"));
  AndroidBridge.syncState(JSON.stringify({
    notify:!!S.settings.notify,date:key,total:due.length,remaining:pending.length,
    am:pending.filter(p=>(p.time||'am')==='am').map(lbl),
    pm:pending.filter(p=>(p.time||'am')==='pm').map(lbl),
    low}));
}catch(e){}}

/* called by the Android shell when "Protocol followed" is tapped in a notification */
window.vialbackAck=function(dateKey){
  try{
    const d=dateKey?parseISO(dateKey):new Date();
    const list=S.track.filter(p=>p.status==="active"&&dueOn(p,d));
    const isToday=iso(d)===iso(new Date());
    S.log[dateKey]=S.log[dateKey]||{};
    let n=0;
    list.forEach(p=>{if(!S.log[dateKey][p.id]){S.log[dateKey][p.id]={dose:p.dose,unit:p.unit,at:Date.now()};
      if(isToday&&!p.label)p.remaining=Math.max(0,round(p.remaining-doseMg(p),3));n++;}});
    if(n){save();if(typeof renderTrack==="function"&&tab==="track")renderTrack();toast("Protocol followed · "+n+" logged");}
  }catch(e){}
};

/* ---------- theme ---------- */
/* dark-first: with no explicit choice saved, use dark rather than following the system */
function applyTheme(){document.documentElement.setAttribute("data-theme",S.settings.theme||"dark");}
/* theme now lives in the quick-settings menu behind the avatar */
applyTheme();

/* ---------- schedule math ---------- */
function dueOn(p,d){const s=p.sched;if(p.status!=="active")return false;
  if(s.t==="daily")return true;if(s.t==="week")return s.days.includes(new Date(d).getDay());return false;}
function doseMg(p){return p.unit==="mcg"?p.dose/1000:p.dose;}
function weeklyMg(p){const s=p.sched,d=doseMg(p);if(s.t==="daily")return d*7;if(s.t==="week")return d*s.days.length;return d;}
function daysLeft(p){const w=weeklyMg(p);if(!w)return null;return Math.floor(p.remaining/(w/7));}
/* Fixed-ratio blends are drawn as one number, but what matters is how much
   of each part is in the pin. Parts are [short name, share, unit to show]. */
const BLENDRATIO={
  tesaipacjc1033:{tot:16,parts:[["tesa",10,"mg"],["ipa",3,"mcg"],["CJC",3,"mcg"]]}
};
function blendSplit(p){
  const r=BLENDRATIO[pepKey(p&&p.name)];
  if(!r||!p.dose||p.unit!=="mg")return "";
  return r.parts.map(([n,sh,u])=>{const mg=p.dose*sh/r.tot;
    return u==="mcg"?`${Math.round(mg*1000)} mcg ${n}`:`${round(mg,2)} mg ${n}`;}).join(" \u00b7 ");
}
function doseLabel(p){
  if(p.label)return p.label;
  const b=blendSplit(p);
  return `${p.dose} ${p.unit}`+(b?` (${b})`:"");
}
function reconUnits(p){if(!p.bacMl||!p.vialMg)return null;const conc=p.vialMg/p.bacMl;return round(doseMg(p)/conc*100,1);}
/* pick a bac-water volume that lands the dose on a clean, even unit mark */
function suggestBac(vialMg,doseMg){const opts=[0.5,1,1.5,2,2.5,3,4,5];let best=null;
  opts.forEach(b=>{const u=doseMg*b/vialMg*100,r=Math.round(u);let sc=0;
    if(Math.abs(u-r)<0.06)sc+=2;if(r%10===0)sc+=3;else if(r%5===0)sc+=2;
    if(u>=15&&u<=90)sc+=2;else if(u<8||u>100)sc-=4;
    if(!best||sc>best.sc||(sc===best.sc&&Math.abs(u-50)<Math.abs(best.u-50)))best={b,u,sc};});
  return best||{b:2,u:doseMg*2/vialMg*100};}
function syrSVG(units){const u=Math.max(0,Math.min(100,units)),x0=16,w=178;
  let t="";for(let i=0;i<=100;i+=10)t+=`<line x1="${x0+w*i/100}" y1="11" x2="${x0+w*i/100}" y2="15" stroke="var(--ink3)" stroke-width="1"/>`;
  return `<svg class="syr" viewBox="0 0 220 40" fill="none"><rect x="${x0-9}" y="9" width="9" height="20" rx="2" fill="var(--line2)"/>
    <rect x="${x0}" y="12" width="${w}" height="14" rx="3" fill="var(--panel)" stroke="var(--line2)"/>
    <rect x="${x0}" y="12" width="${w*u/100}" height="14" rx="3" fill="var(--accent)" opacity="0.85"/>${t}
    <line x1="${x0+w}" y1="19" x2="216" y2="19" stroke="var(--ink3)" stroke-width="2"/>
    <line x1="${x0+w*u/100}" y1="7" x2="${x0+w*u/100}" y2="31" stroke="var(--accent-ink)" stroke-width="2"/></svg>`;}

/* ============ HOME (week strip + action cards) ============ */
let selDay=new Date();
let calMode="week";           // week strip, or the month grid inside Settings
let legendOpen=false;         // colour key sits behind the "i" and starts closed every launch
function weekStart(d){const x=new Date(d);x.setDate(x.getDate()-x.getDay());x.setHours(0,0,0,0);return x;}
function weeklyGoal(){return S.settings.weeklyGoal||6;}
function workoutsThisWeek(){
  const ws=weekStart(new Date()),we=new Date(+ws+7*DAY);
  return S.workouts.filter(w=>{const d=parseISO(w.date);return d>=ws&&d<we&&(w.exercises||[]).some(e=>exDone(e));}).length;
}
function renderTrack(){
  const el=$("#v-track");
  const tdKey=iso(new Date()),key=iso(selDay),isToday=key===tdKey;
  const active=activeTrack();
  const due=active.filter(p=>dueOn(p,selDay));
  const logd=S.log[key]||{};
  const doneDoses=due.filter(p=>logd[p.id]).length;
  const wk=workoutFor(key);
  const meals=S.meals.filter(m=>m.date===key);
  const kcal=meals.reduce((a,m)=>a+(+m.kcal||0),0);
  const goal=weeklyGoal(),got=workoutsThisWeek();

  /* week strip */
  const ws=weekStart(selDay);
  let strip="";
  for(let i=0;i<7;i++){
    const d=new Date(+ws+i*DAY),dk=iso(d);
    const dd=active.filter(p=>dueOn(p,d)).length;
    const dl=Object.keys(S.log[dk]||{}).length;
    const dw=workoutFor(dk);
    strip+=`<button class="wday ${dk===key?'on':''} ${dk===tdKey?'td':''}" data-day="${dk}">
      <span class="wdn">${WD[d.getDay()]}</span><span class="wdd">${d.getDate()}</span>
      <span class="wdots">${dd?`<i class="wd pep ${dl>=dd?'full':''}"></i>`:""}${dw?`<i class="wd wk ${(dw.exercises||[]).every(e=>exDone(e))?'full':''}"></i>`:""}${S.meals.some(m=>m.date===dk)?`<i class="wd fd"></i>`:""}</span>
    </button>`;
  }

  /* workout card */
  let wcard;
  if(wk){
    const r=ROUTINES[wk.routine],st=wkStats(wk);
    const targets=[...new Set((wk.exercises||[]).flatMap(e=>exInfo(e.n).m))]
      .map(m=>(MUSCLES.find(x=>x.id===m)||{}).n).filter(Boolean);
    const doneEx=(wk.exercises||[]).filter(exDone).length;
    const complete=doneEx===(wk.exercises||[]).length&&doneEx>0;
    wcard=`<div class="bigcard wcard">
      <div class="bcart">${miniBody([...new Set((wk.exercises||[]).flatMap(e=>exInfo(e.n).m))],wk.routine==="pull"?"b":"f")}</div>
      <div class="bcin">
        <div class="bctitle">${r?r.n:"Workout"}</div>
        <div class="bcsub">${targets.slice(0,4).join(", ")}</div>
        <div class="bcsub dim">${st.mins} min · ${st.count} exercises${complete?" · done":doneEx?` · ${doneEx}/${st.count}`:""}</div>
        <div class="bcbtns"><button class="bcgo ${complete?'ghosted':''}" data-go="workout">${complete?"✓ Completed":doneEx?"RESUME":"START"}</button>
          <button class="bcedit" data-go="workout-edit" aria-label="Edit workout">✎</button></div>
      </div></div>`;
  }else{
    wcard=`<div class="bigcard wcard empty">
      <div class="bcart">${miniBody([],"f")}</div>
      <div class="bcin"><div class="bctitle">Workout</div>
        <div class="bcsub">No session picked for this day</div>
        <div class="bcbtns"><button class="bcgo" data-go="workout">CHOOSE</button></div></div></div>`;
  }

  el.innerHTML=`
    <div class="goalwrap"><div class="goallbl">Weekly goal</div>
      <div class="goalbars">${Array.from({length:goal},(_,i)=>`<i class="${i<got?'on':''}"></i>`).join("")}</div>
      <div class="goalnum">${got}/${goal} workouts</div></div>
    <div class="weekbar">
      <button class="wnav" id="wPrev" aria-label="Previous week">‹</button>
      <div class="wdays">${strip}</div>
      <button class="wnav" id="wNext" aria-label="Next week">›</button>
    </div>
    <div class="dayline"><span class="dlbig">${isToday?"Today":selDay.toLocaleDateString('en-US',{weekday:'long'})}</span>
      <span class="dlsm">${selDay.toLocaleDateString('en-US',{month:'long',day:'numeric'})}</span>
      <span class="spacer"></span></div>
    <div class="cardstack">
      ${wcard}
      <div class="bigcard pcard">
        <div class="bcring"><div class="ring2" style="--p:${due.length?doneDoses/due.length*100:0}"><span>${doneDoses}<small>/${due.length}</small></span></div></div>
        <div class="bcin"><div class="bctitle">Peptides</div>
          <div class="bcsub">${due.length?`${due.filter(p=>(p.time||'am')==='am').length} morning · ${due.filter(p=>p.time==='pm').length} night`:"Nothing scheduled"}</div>
          <div class="bcsub dim">${due.length?(doneDoses>=due.length?"All logged":`${due.length-doneDoses} left today`):"—"}</div>
          <div class="bcbtns"><button class="bcgo ${doneDoses>=due.length&&due.length?'ghosted':''}" data-go="peps">${due.length?(doneDoses>=due.length?"✓ Logged":"OPEN LIST"):"OPEN LIST"}</button></div>
        </div></div>
      ${due.length?`<div class="bigcard shotcard">
        ${["am","pm"].map(half=>{const list=due.filter(p=>(p.time||"am")===half);
          if(!list.length)return "";
          return `<div class="pephalf"><div class="lbl">${half==="am"?"☀ Morning":"☾ Night"}
            <span class="pepnone">${list.filter(p=>logd[p.id]).length}/${list.length}</span></div>
            <div class="pepwrap">${list.map(p=>pepBox(p,{done:!!logd[p.id],
              attr:` data-shot="${p.id}" role="button" tabindex="0"`})).join("")}</div></div>`;}).join("")}
        <button class="keybtn ${legendOpen?"on":""}" id="famKeyBtn" aria-label="What the colours mean">i</button>
        ${legendOpen?`<div class="famkey">${[...new Set(due.flatMap(p=>pepFams(p)))]
          .map(f=>`<span><i style="background:${(PFAM[f]||PFAM.other).c}"></i>${(PFAM[f]||PFAM.other).n}</span>`).join("")}</div>`:""}
      </div>`:""}
      <div class="bigcard fcard">
        <div class="bcring"><div class="ring2 ${S.macros.kcal&&kcal>S.macros.kcal?"over":"gold"}" style="--p:${S.macros.kcal?Math.min(100,kcal/S.macros.kcal*100):0}"><span>${Math.round(kcal/100)/10||0}<small>k</small></span></div></div>
        <div class="bcin"><div class="bctitle">Nutrition</div>
          <div class="bcsub${S.macros.kcal&&kcal>S.macros.kcal?" over":""}">${Math.round(kcal)} / ${S.macros.kcal} kcal${S.macros.kcal&&kcal>S.macros.kcal?` · ${Math.round(kcal-S.macros.kcal)} over`:""}</div>
          <div class="bcsub dim">${meals.length} item${meals.length===1?"":"s"} logged</div>
          <div class="bcbtns"><button class="bcgo" data-go="food">LOG FOOD</button></div>
        </div></div>
      ${cycSetupCard()}
      ${(()=>{const c=insightCards(3);return c?`<div class="inshead"><span class="ih">What connects</span><i class="il"></i></div>${c}`:"";})()}
    </div>`;

  $$("[data-cysetup]",el).forEach(b=>b.onclick=()=>{
    const v=b.dataset.cysetup;
    if(v==="skip")cycS().skip=1;else cycS().sex=v;
    save();syncCycBtn();renderTrack();
    if(v!=="skip")setTab("cycle");});
  if($("#insMore"))$("#insMore").onclick=insightsPop;
  $("#wPrev").onclick=()=>{selDay=new Date(+selDay-7*DAY);renderTrack();};
  $("#wNext").onclick=()=>{selDay=new Date(+selDay+7*DAY);renderTrack();};
  $$("[data-day]",el).forEach(b=>{if(!b.classList.contains('empty'))b.onclick=()=>{selDay=parseISO(b.dataset.day);renderTrack();};});
  if($("#famKeyBtn"))$("#famKeyBtn").onclick=()=>{legendOpen=!legendOpen;renderTrack();};
  // tap a colour box to log that shot straight from the day's list
  $$("[data-shot]",el).forEach(b=>{
    const go=()=>{toggleDay2(b.dataset.shot,key,isToday);renderTrack();};
    b.onclick=go;
    b.onkeydown=ev=>{if(ev.key==="Enter"||ev.key===" "){ev.preventDefault();go();}};
  });
  $$("[data-go]",el).forEach(b=>b.onclick=()=>{
    const g=b.dataset.go;
    // the workout lives in the Gym tab now, not a floating sheet
    if(g==="workout"){setTab("gym");
      const w=workoutFor(iso(selDay));
      if(w&&(w.exercises||[]).some(e=>!exDone(e)))setTimeout(()=>{const b=$("#gymStart");if(b)b.click();},80);
      return;}
if(g==="workout-edit"){dayTab="workout";openDay(true);return;}
    // the peptides card goes to the Peps tab rather than the floating day sheet
    if(g==="peps"){setTab("guide");return;}
    // straight to the Food tab — the day sheet still carries the old
    // peptide and workout tabs, which only confuses things from here
    if(g==="food"){setTab("food");return;}
  });
}
function monthGrid(key,tdKey){
  const y=selDay.getFullYear(),m=selDay.getMonth();
  const active=activeTrack();
  const logKeys=Object.keys(S.log).sort();
  const firstLog=logKeys.length?logKeys[0]:null;
  const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
  let cells="";for(let i=0;i<first;i++)cells+=`<div class="hcell empty"></div>`;
  for(let d=1;d<=days;d++){const dk=iso(new Date(y,m,d));
    const due=active.filter(p=>dueOn(p,new Date(y,m,d))).length,logged=Object.keys(S.log[dk]||{}).length;
    const wk=workoutFor(dk);
    const kcal=S.meals.filter(x=>x.date===dk).reduce((a,x)=>a+(+x.kcal||0),0);
    const rl={upper:"U",lower:"L",pull:"P"}[wk&&wk.routine]||(wk?"W":null);
    const wkDone=wk&&(wk.exercises||[]).length&&(wk.exercises||[]).every(e=>exDone(e));
    const tracked=firstLog&&dk>=firstLog&&dk<=tdKey;
    let pep="";
    if(due){const pct=Math.min(100,logged/due*100);
      pep=`<div class="pbar ${logged>=due?'full':(logged===0&&tracked?'miss':'')}"><i style="width:${pct}%"></i></div>`;}
    let badges="";
    if(due)badges+=`<span class="dbadge ${logged>=due?'full':''}">${logged}/${due}</span>`;
    if(rl)badges+=`<span class="wbadge ${wkDone?'done':''}">${rl}</span>`;
    if(kcal)badges+=`<span class="fbadge">${kcal>=1000?(kcal/1000).toFixed(1)+"k":Math.round(kcal)}</span>`;
    // shade the cell by what actually happened that day, so the month reads at a glance
    const anything=logged>0||wk||kcal>0;
    const allDone=due>0&&logged>=due&&(!wk||wkDone);
    const cls=[dk===key?"sel":"",dk===tdKey?"tod":"",allDone?"done":anything?"has":"",dk>tdKey?"future":""]
      .filter(Boolean).join(" ");
    cells+=`<div class="hcell ${cls}" data-day="${dk}">
      <span class="hn">${d}</span>${pep}<span class="hbadges">${badges}</span></div>`;}
  return `<div class="hgrid"><div class="hd">Su</div><div class="hd">Mo</div><div class="hd">Tu</div><div class="hd">We</div><div class="hd">Th</div><div class="hd">Fr</div><div class="hd">Sa</div>${cells}</div>`;
}
/* ---------- exercise library: muscles, equipment, cues, variants ----------
   Every movement belongs to a family (chest press, row, leg curl...), so any
   exercise can be swapped for the cable / dumbbell / machine version of the
   same movement. Cues and photos come from free-exercise-db (public domain). */
