const EQORDER=["cable","dumbbell","machine","barbell","body"];
const FAMN={chestpress:"Chest press",inclinepress:"Incline press",chestfly:"Chest fly",tricepext:"Triceps extension",bicepcurl:"Biceps curl",hammercurl:"Neutral-grip curl",wristcurl:"Forearm / grip",shoulderpress:"Overhead press",lateralraise:"Delt raise",reardelt:"Rear delt",shrug:"Shrug",uprightrow:"Upright row",row:"Row",pulldown:"Vertical pull",squat:"Squat / press",lunge:"Lunge / split",legext:"Leg extension",legcurl:"Leg curl",hinge:"Hip hinge",calfraise:"Calf raise",core:"Core"};
