/* ---------- training splits ----------
   A split is which days exist and in what order. The routines are the same
   shape whichever split names them, so adding one is adding a list. */
const SPLITS={
 plr:{n:"Push · Legs · Pull",days:["upper","lower","pull"],
  sub:"Three days. Everything that presses, then legs, then everything that pulls.",
  note:"Each muscle gets trained once per rotation with a clear job per day, which makes it easy to see whether a session went well. It is the least complicated way to cover the whole body and the easiest to keep to when the week goes wrong."},
 bpart:{n:"Four-day body part",days:["sChest","sBack","sArms","sLegs"],
  sub:"Chest, back, arms, legs, rotating with no fixed rest days.",
  note:"Fewer muscles per session, so each gets more attention and more recovery before it comes round again. Low set counts and high effort: two to three working sets an exercise, eight to twelve reps, taken to or near failure with a slow lowering phase. Mostly machines and cables, because that is what lets you reach failure without a spotter. Rotate when you are ready rather than on fixed days."}};
function curSplit(){
  return SPLITS[(S.settings&&S.settings.split)||"plr"]||SPLITS.plr;
}
function workoutFor(dateKey){return S.workouts.find(w=>w.date===dateKey)||null;}
function exHistory(name){
  const out=[];
  S.workouts.forEach(w=>{(w.exercises||[]).forEach(e=>{if(e.n===name&&e.done)out.push({date:w.date,r:e.r,w:e.w,s:e.s});});});
  return out.sort((a,b)=>b.date.localeCompare(a.date));
}

