 tesamorelin:["ghrhr"], sermorelin:["ghrhr"], cjc1295nodac:["ghrhr"],tesaipacjc1033:["ghrhr","ghsr"], ipamorelin:["ghsr"],
 kisspeptin10:["kiss1r"], kisspeptin:["kiss1r"],
 pt141:["mc4r"], mt2:["mc4r"],
 ace031:["actriib"], epo:["epor"],
 thymosinalpha1:["thymic"], thymalin:["thymic"],
