function medList(){return (S.meds=S.meds||[]);}
function medOn(k){return medList().indexOf(k)>=0;}
function medToggle(k){
  const m=medList(),i=m.indexOf(k);
  if(i>=0)m.splice(i,1);else m.push(k);
  save();
}
/* every interaction between a recorded prescription and something tracked */
function medHits(){
  const out=[];
  medList().forEach(mk=>{
    const med=MEDS[mk];
    if(!med)return;
    (med.hits||[]).forEach(h=>{
      const peps=activeTrack().filter(p=>{
        if(p.label)return false;
        if(h.key)return guideKeyFor(p.name)===h.key;
        return pepFams(p).indexOf(h.fam)>=0;
      });
      if(peps.length)out.push({med:med.n,mk:mk,lvl:h.lvl,t:h.t,
        peps:peps.map(p=>p.name)});
    });
  });
  return out;
}

/* ================= CYCLE AND RHYTHM ==================
   Guidance here is driven by what gets logged, not by what phase the calendar
   says. Current evidence does not support prescribing training intensity by
   cycle phase; symptoms and readiness track performance far better, and those
   are the thing being logged anyway. Phase is shown as context. */
function cycS(){
  const c=S.cycle=S.cycle||{};
  c.sex=c.sex||""; c.periods=c.periods||[]; c.days=c.days||{};
  return c;
}
function cycSex(){return cycS().sex;}
function cycOn(){return cycSex()==="f"||cycSex()==="m";}
function cycStarts(){return cycS().periods.map(p=>p.start).filter(Boolean).sort();}

/* Cycle length learned from logged starts. Gaps outside 18-45 days are almost
   always a mislog or a skipped entry, so they are dropped rather than allowed
   to drag the mean around. */
function cycGaps(){
  const st=cycStarts(),out=[];
  for(let i=1;i<st.length;i++){
    const g=Math.round((parseISO(st[i]).getTime()-parseISO(st[i-1]).getTime())/DAY);
    if(g>=18&&g<=45)out.push(g);
  }
  return out;
}
function cycAvg(){
  const g=cycGaps();
  if(!g.length)return 28;
  return Math.round(g.reduce((a,b)=>a+b,0)/g.length);
}
/* How much those gaps move about. This is the number every tracker hides. */
function cycSpread(){
  const g=cycGaps();
  if(g.length<2)return null;
  return Math.max.apply(null,g)-Math.min.apply(null,g);
}
function cycConfidence(){
  const g=cycGaps(),sp=cycSpread();
  if(g.length<2)return {lvl:"none",n:g.length,sp:sp};
  if(sp<=3)return {lvl:"good",n:g.length,sp:sp};
  if(sp<=7)return {lvl:"rough",n:g.length,sp:sp};
  return {lvl:"wide",n:g.length,sp:sp};
}
function cycAvgBleed(){
  const p=cycS().periods.filter(x=>x.start&&x.end);
  if(!p.length)return 5;
  const d=p.map(x=>Math.round((parseISO(x.end).getTime()-parseISO(x.start).getTime())/DAY)+1)
           .filter(x=>x>=1&&x<=12);
  if(!d.length)return 5;
  return Math.round(d.reduce((a,b)=>a+b,0)/d.length);
}
function cycLastStart(){const st=cycStarts();return st.length?st[st.length-1]:null;}
/* The cycle containing a date: its start, its length, and where the date sits
   in it. Counting forward from only the most recent start left every earlier
   date with no phase at all. */
function cycAt(dt){
  const k=iso(dt),st=cycStarts();
  if(!st.length)return null;
  let idx=-1;
  for(let n=0;n<st.length;n++){if(st[n]<=k)idx=n;else break;}
  if(idx<0)return null;                       // before anything was logged
  const start=st[idx];
  const len=st[idx+1]
    ? Math.round((parseISO(st[idx+1]).getTime()-parseISO(start).getTime())/DAY)
    : cycAvg();
  const day=Math.round((parseISO(k).getTime()-parseISO(start).getTime())/DAY)+1;
  // a gap far longer than a cycle means a missed log, not a 60 day cycle
  if(day>Math.max(len,45)+10)return null;
  return {start:start,len:len,day:day,
          next:st[idx+1]||iso(new Date(parseISO(start).getTime()+len*DAY))};
}
/* 1-based day within the cycle containing this date */
function cycDay(dt){
  const c=cycAt(dt);
  return c?c.day:null;
}
/* The luteal phase is the stable part of the cycle at roughly 14 days, so
   ovulation is estimated back from the next expected period, not forward from
   the last one. That is what keeps it honest on long or short cycles. */
function cycPredict(){
  const ls=cycLastStart();
  if(!ls)return null;
  const avg=cycAvg(),bleed=cycAvgBleed();
  const start=parseISO(ls);
  const next=new Date(start.getTime()+avg*DAY);
  const ov=new Date(next.getTime()-14*DAY);
  return {
    lastStart:ls, avg:avg, bleed:bleed,
    nextStart:iso(next),
    ovulation:iso(ov),
    fertileFrom:iso(new Date(ov.getTime()-5*DAY)),
    fertileTo:iso(new Date(ov.getTime()+DAY)),
    bleedTo:iso(new Date(start.getTime()+(bleed-1)*DAY))
  };
}
function cycPhase(dt){
  const c=cycAt(dt);
  if(!c)return null;
  const bleed=cycAvgBleed();
  if(c.day<=bleed)return "menstrual";
  // ovulation sits 14 days before the NEXT start, so it moves with each
  // cycle's real length rather than being pinned to a global average
  const ov=Math.round((parseISO(c.next).getTime()-parseISO(c.start).getTime())/DAY)-14+1;
  if(c.day>=ov-5&&c.day<=ov+1)return "ovulation";
  if(c.day>ov+1)return "luteal";
  return "follicular";
}
/* Is this date inside a logged bleed, rather than a predicted one? */
function cycBleedOn(k){
  return cycS().periods.some(p=>p.start&&k>=p.start&&k<=(p.end||p.start));
}
/* Every ovulation this app believes in, logged cycles and projected ones.
   For a cycle that has a following start we know its real length, so we count
   back 14 days from that. For the ones after the last logged period we count
   back from the running average instead. */
function cycOvDates(){
  const st=cycStarts(),avg=cycAvg(),out=[];
  for(let i=0;i<st.length;i++){
    const next=st[i+1]?parseISO(st[i+1]).getTime()
                      :parseISO(st[i]).getTime()+avg*DAY;
    out.push(iso(new Date(next-14*DAY)));
  }
  if(st.length){
    const last=parseISO(st[st.length-1]).getTime();
    for(let n=1;n<=3;n++)out.push(iso(new Date(last+avg*n*DAY-14*DAY)));
  }
  return out;
}
function cycPredBleedOn(k){
  const st=cycStarts();
  if(!st.length)return false;
  const avg=cycAvg(),bleed=cycAvgBleed(),last=parseISO(st[st.length-1]).getTime();
  for(let n=1;n<=3;n++){
    const a=new Date(last+avg*n*DAY);
    const b=new Date(a.getTime()+(bleed-1)*DAY);
    if(k>=iso(a)&&k<=iso(b))return true;
  }
  return false;
}
function cycFertileOn(k){
  return cycOvDates().some(o=>{
    const t=parseISO(o).getTime();
    return k>=iso(new Date(t-5*DAY))&&k<=iso(new Date(t+DAY));
  });
}
function cycOvOn(k){return cycOvDates().indexOf(k)>=0;}
/* One period is one run of consecutive days. Editing days in any order has to
   end at the same answer, so every edit re-sorts and merges: two runs that
   overlap or merely touch are the same period. Without this, marking 19 then
   17 then 18 leaves 17-18 and 19-19 as separate cycle starts and every
   prediction after them is computed from a two-day cycle. */
function cycNormalise(){
  const c=cycS();
  const day=k=>parseISO(k).getTime();
  let p=(c.periods||[])
    .filter(x=>x&&x.start)
    .map(x=>({start:x.start,end:(x.end&&x.end>=x.start)?x.end:x.start}))
    .sort((a,b)=>a.start<b.start?-1:a.start>b.start?1:0);
  const out=[];
  p.forEach(cur=>{
    const last=out[out.length-1];
    // touching counts as continuous: end + 1 day reaching the next start
    if(last&&day(cur.start)<=day(last.end)+DAY){
      if(cur.end>last.end)last.end=cur.end;
    }else out.push(cur);
  });
  c.periods=out;
  return out;
}
/* start or extend a bleed on this date, or clear it */
function cycToggleBleed(k){
  const c=cycS();
  const hit=c.periods.find(p=>p.start&&k>=p.start&&k<=(p.end||p.start));
  if(hit){
    const end=hit.end||hit.start;
    if(hit.start===k&&end===k)c.periods=c.periods.filter(p=>p!==hit);
    else if(k===hit.start)hit.start=iso(new Date(parseISO(k).getTime()+DAY));
    else if(k===end)hit.end=iso(new Date(parseISO(k).getTime()-DAY));
    else{
      // unmarking a day in the middle splits the run in two; the old code
      // truncated it and silently discarded every day after the one removed
      const tail={start:iso(new Date(parseISO(k).getTime()+DAY)),end:end};
      hit.end=iso(new Date(parseISO(k).getTime()-DAY));
      c.periods.push(tail);
    }
  }else{
    // extend an adjacent run rather than starting a second one next to it
    const prev=c.periods.find(p=>iso(new Date(parseISO(p.end||p.start).getTime()+DAY))===k);
    const nextp=c.periods.find(p=>iso(new Date(parseISO(p.start).getTime()-DAY))===k);
    if(prev)prev.end=k;
    else if(nextp)nextp.start=k;
    else c.periods.push({start:k,end:k});
  }
  cycNormalise();
  save();
}

/* ---------- mood, taken at face value ----------
   Opposing moods on one day are a swing, not a conflict to be resolved. The
   pattern is the point: how often it happens, and where in the cycle. */
const MOODPOL={
 "Calm":1,"Happy":1,"Energetic":1,"Frisky":1,"Motivated":1,"Confident":1,
 "Sad":-1,"Anxious":-1,"Low":-1,"Feeling guilty":-1,"Obsessive thoughts":-1,
 "Low energy":-1,"Apathetic":-1,"Confused":-1,"Very self-critical":-1,
 "Irritated":-1,"Angry":-1,"Flat":-1,"Foggy":-1,"Restless":-1
};
/* a day counts as a swing if it holds moods from both poles, or if the person
   said so outright */
function cycSwing(k){
  const m=(cycDayLog(k).mood)||[];
  if(m.indexOf("Mood swings")>=0)return true;
  let up=0,down=0;
  m.forEach(o=>{const p=MOODPOL[o];if(p>0)up++;else if(p<0)down++;});
  return up>0&&down>0;
}
/* logged days in a window, with the swing count */
function cycMoodStats(win){
  const c=cycS(),out={days:0,swings:0,tally:{},sym:{},byPhase:{}};
  Object.keys(c.days).forEach(k=>{
    if(win){
      const age=Math.round((Date.now()-parseISO(k).getTime())/DAY);
      if(age<0||age>win)return;
    }
    const d=c.days[k];
    if(!(d.mood||d.sym))return;
    out.days++;
    const sw=cycSwing(k);
    if(sw)out.swings++;
    (d.mood||[]).forEach(o=>out.tally[o]=(out.tally[o]||0)+1);
    (d.sym||[]).forEach(o=>{if(o!=="Everything is fine")out.sym[o]=(out.sym[o]||0)+1;});
    const ph=cycSex()==="f"?cycPhase(parseISO(k)):null;
    if(ph){
      const b=out.byPhase[ph]=out.byPhase[ph]||{days:0,swings:0};
      b.days++; if(sw)b.swings++;
    }
  });
  return out;
}
function topN(obj,n){
  return Object.keys(obj).sort((a,b)=>obj[b]-obj[a]).slice(0,n);
}
