    const g=(lc==="en"&&GUIDES[key])||guideView({name:key,guideKey:key})||GUIDES[key];
    push(key,SEC("What it is"),g.what,3);
    push(key,SEC("How it works"),g.mech,3);
    push(key,SEC("Dosing"),g.dose,2);
    push(key,SEC("What people report"),g.anec,1.5);
    (g.key||[]).forEach(x=>push(key,SEC("Get this right"),x,3));
    (g.warn||[]).forEach(x=>push(key,SEC("Before you dose"),x,2.5));
    (g.good||[]).forEach(x=>push(key,SEC("Worth it because"),x,1.5));
    (g.bad||[]).forEach(x=>push(key,SEC("Against it"),x,2));
    (g.ev||[]).forEach(e=>push(key,SEC(e[0]==="human"?"What's established":e[0]==="pre"?"What's suggested":"What's unknown"),e[1],1));
    (g.prac||[]).forEach(p=>push(key,p[0],p[1],2.5));
