const LABBY=(()=>{const o={};LABS.forEach(l=>{(o[l.c]=o[l.c]||[]).push(l);});return o;})();
function labDef(k){return LABS.find(l=>l.k===k);}
function labCat(id){return LABCATS.find(c=>c.id===id)||{n:id,c:"var(--ink3)"};}
/* verdict on a single value: optimal / ok / out of range */
function labStatus(def,v){
  if(def==null||v==null||isNaN(v))return{s:"none",n:"—"};
  const inRange=v>=def.lo&&v<=def.hi;
  const inOpt=def.opt&&v>=def.opt[0]&&v<=def.opt[1];
  if(inOpt)return{s:"opt",n:"Optimal"};
  if(inRange)return{s:"ok",n:"In range"};
  return v<def.lo?{s:"lowout",n:"Below range"}:{s:"highout",n:"Above range"};
}
const LABC={opt:"var(--good)",ok:"var(--warn)",lowout:"var(--crit)",highout:"var(--crit)",none:"var(--mut)"};

