/* pattern prefixes: "Edit <name>", "Log <name>", "<name> history" */
const MONRE="January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec";
const DOWRE="Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|Mon|Tue|Wed|Thu|Fri|Sat|Sun";
const LANGPAT={
 es:[/* specific before general: the bare ^Log rule below would otherwise
        swallow "3 to Left abdomen" whole */
     [/^Log (\d+) to (.+)$/,"Registrar $1 en $2",[2]],
     [/^Log to (.+)$/,"Registrar en $1",[1]],
     [/^Total in the barrel:$/,"Total en la jeringa:"],
     /* the site figure's tooltip: "Left abdomen \u2014 never" */
     [/^(.+) \u2014 (never|today|\d+d)$/,"$1 \u2014 $2",[1,2]],
     /* the reconstitution preview in the vial editor */
     [/^Recon: at (.+?) in (.+?), your (.+?) dose =$/,
      "Recon: con $1 en $2, tu dosis de $3 ="],
     [/^on a U-100 insulin syringe\.$/,"en una jeringa de insulina U-100."],
     [/^Enter vial size and bac water for the syringe maths\.$/,
      "Introduce el tama\u00f1o del vial y el agua bacteriost\u00e1tica para el c\u00e1lculo de la jeringa."],
     [/^(\d+(?:\.\d+)?) units$/,"$1 unidades"],
     [/^Edit (.+)$/,"Editar $1"],[/^Log (.+?)( anyway)?$/,"Registrar $1"],
     [/^(.+) history$/,"Historial de $1"],[/^(.+) range$/,"Rango de $1"],
     /* dates: Spanish puts the day first and lowercases the month */
     [new RegExp("^("+DOWRE+"), ("+MONRE+") (\\d{1,2})$"),"$1, $3 de $2",[1,2]],
     [new RegExp("^("+MONRE+") (\\d{4})$"),"$1 de $2",[1]],
     [new RegExp("^("+MONRE+") (\\d{1,2})$"),"$2 de $1",[1]],
     [new RegExp("^out ("+MONRE+") (\\d{1,2})$"),"se acaba el $2 de $1",[1]],
     [new RegExp("^("+DOWRE+")$"),"$1",[1]],
     /* counts and units */
     [/^(\d+) left today$/,"quedan $1 hoy"],
     [/^([\d.,]+) kcal left today$/,"quedan $1 kcal hoy"],
     [/^([\d.,]+) (mg|mcg|ml|g|IU|UI) left$/,"quedan $1 $2"],
     [/^(\d+) more$/,"$1 m\u00e1s"],
     [/^(\d+) items? logged$/,"$1 alimentos registrados"],
     [/^(\d+)\/(\d+) workouts$/,"$1/$2 entrenamientos"],
     [/^(\d+) groups?$/,"$1 grupos"],
     [/^(\d+) morning . (\d+) night$/,"$1 ma\u00f1ana · $2 noche"],
     [/^(\d+) exercises? . (.+)$/,"$1 ejercicios · $2",[2]],
     [/^(\d+) kcal . P(\d+) C(\d+) F(\d+)$/,"$1 kcal · P$2 C$3 G$4"],
     [/^(\d+)w ago$/,"hace $1 sem"],
     [/^(.+) trials$/,"Ensayos de $1"],
     [/^([\d.,]+) \/ ([\d.,]+) (mg|mcg|ml|g|IU|UI) left$/,"quedan $1 / $2 $3"],
     [/^(.+) . logged\. Tap a spot, or skip\.$/,"$1 \u00b7 registrado. Toca un sitio, u omite."],
     [/^optimal (.+)$/,"\u00f3ptimo $1"],
     [/^([\d.,]+) (mg|mcg|ml|g|IU|UI) . (.+)$/,"$1 $2 · $3",[3]],
     [/^\u00b7 ([\d.,]+) (mg|mcg|ml|g|IU|UI) . (.+)$/,"\u00b7 $1 $2 · $3",[3]],
     /* the guide count is interpolated, so the note can only be matched as a shape */
     [/^Answers come from the (\d+) guides[\s\S]*$/,
      "Las respuestas salen de las $1 gu\u00edas de esta app y de tus propios datos registrados. No se genera nada y nada sale de tu tel\u00e9fono, as\u00ed que no puede inventarse un estudio ni una dosis \u2014 cada respuesta muestra de d\u00f3nde viene."]],
 ar:[[/^Edit (.+)$/,"تعديل $1"],[/^Log (.+?)( anyway)?$/,"تسجيل $1"],
     [/^(.+) history$/,"سجل $1"],[/^(.+) range$/,"نطاق $1"]],
 zh:[[/^Edit (.+)$/,"编辑 $1"],[/^Log (.+?)( anyway)?$/,"记录 $1"],
     [/^(.+) history$/,"$1 历史"],[/^(.+) range$/,"$1 范围"]],
 ru:[[/^Edit (.+)$/,"Изменить $1"],[/^Log (.+?)( anyway)?$/,"Записать $1"],
     [/^(.+) history$/,"История $1"],[/^(.+) range$/,"Диапазон $1"]]
};

function curLang(){
  const c=(S.settings&&S.settings.lang)||"en";
  /* a language that has since been gated off falls back rather than
     half-rendering a screen */
  if(c!=="en"&&typeof langReady==="function"&&!langReady(c))return "en";
  return c;
}
function tr(str,lc){
  const d=I18N[lc];if(!d)return null;
  const t=str.trim();
  if(NOTR.has(t))return null;
  if(d[t]!=null)return d[t];
  /* Prose split across two lines in a template literal arrives with the
     newline and the file's indentation inside it. Collapsing runs of
     whitespace means a translation can be keyed by the sentence rather than
     by how the source happened to be wrapped. */
  const flat=t.replace(/\s+/g," ");
  if(flat!==t&&d[flat]!=null)return d[flat];
  // composed lists ("Immune + Gut + Copper", "Chest, Triceps") translate part by part
  for(const sep of [" + ",", "," \u00b7 "]){
    if(t.includes(sep)){
      const parts=t.split(sep);
      if(parts.length>1&&parts.every(x=>d[x.trim()]!=null))
        return parts.map(x=>d[x.trim()]).join(sep);
    }
  }
  for(const pat of (LANGPAT[lc]||[])){
    const re=pat[0],rep=pat[1],deep=pat[2];
    const m=t.match(re);
    if(m){
      // $1..$9 fill from the capture groups; groups listed in deep are
      // themselves run back through tr(), so "7 exercises - Traps, Calves"
      // translates the muscle names too instead of only the wrapper
      const out=rep.replace(/\$([1-9])/g,(_,d)=>{
        const g=m[+d];
        if(g==null)return "";
        if(!deep||deep.indexOf(+d)<0)return g;
        const whole=tr(g,lc);
        if(whole!=null)return whole;
        if(g.indexOf(", ")>=0)
          return g.split(", ").map(x=>{const v=tr(x.trim(),lc);return v!=null?v:x.trim();}).join(", ");
        return g;
      });
      /* A rule that fires on a phrase it only half understands produces
         "Ensayos de NAD+ and precursor". These words are English and are not
         also Spanish, so one surviving in the output means the rule did not
         translate the string. Leave the English alone rather than shipping
         half of each. */
      if(/\b(and|the|with|for|from|about|into|over|after|before|your|you|this|that|which|what|when|research|trials|study|studies|improves|older|adults|single)\b/i.test(out))
        continue;
      return out;
    }
  }
  return null;
}
/* user-entered content and proper nouns live here — never touched */
/* .pbn does double duty: the peptide name inside a pepbox, which must never
   be translated, and the band headers of the peptide list, which must be. Only
   the first one is a name. */
const TRSKIP=".gname,.pepbox .pbn,.dn,.excn,.pname,.pexname,.altn,.rp,.lrn,.ddname,.rn,.molimg,.mono,.notr,"+
  /* guide prose is translated by id through guideView, so the text walker must
     leave it alone rather than trying to match paragraphs against the UI dict */
  ".ddblock li,.ddlede,.ddsec p,.ddp,.ddkey li,.ddwarn li,.ddcol li,.ddalias,.akan";
/* Translating in place is destructive — once "Today" becomes "Hoy" the English
   key is gone and no further switch can find it. So the original is stashed the
   first time a node is seen, and every pass translates from that. */
const TRORIG=new WeakMap();
function applyLang(){
  const lc=curLang();
  const L=LANGS.find(x=>x.c===lc)||LANGS[0];
  document.documentElement.lang=lc;
  document.documentElement.dir=L.rtl?"rtl":"ltr";
  document.body.classList.toggle("rtl",!!L.rtl);
  const skipTags=new Set(["SCRIPT","STYLE","IMG","INPUT","TEXTAREA"]);
  const tw=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  const jobs=[];
  let n;
  while(n=tw.nextNode()){
    const p=n.parentElement;
    if(!p||skipTags.has(p.tagName)||p.closest(TRSKIP))continue;
    let base=TRORIG.get(n);
    if(base===undefined){base=n.textContent;TRORIG.set(n,base);}
    const t=base.trim();
    if(!t||t.length<2||!/[A-Za-z]/.test(t))continue;
    const hit=lc==="en"?null:tr(t,lc);
    const val=hit!=null?base.replace(t,hit):base;
    if(val!==n.textContent)jobs.push([n,val]);
  }
  jobs.forEach(([node,val])=>{node.textContent=val;});
  const attr=(sel,name)=>document.querySelectorAll(sel).forEach(e=>{
    let base=e.getAttribute("data-en-"+name);
    if(base==null){base=e.getAttribute(name)||"";e.setAttribute("data-en-"+name,base);}
    const h=lc==="en"?null:tr(base,lc);
    e.setAttribute(name,h!=null?h:base);
  });
  attr("[placeholder]","placeholder");
  attr("[aria-label]","aria-label");
}

/* Sheets and overlays are built by many different functions, so rather than
   patching each one, watch their containers and translate whatever appears. */
let langObs=null;
function watchLang(){
  if(langObs||typeof MutationObserver!=="function")return;
  let queued=false;
  langObs=new MutationObserver(()=>{
    if(queued||curLang()==="en")return;
    queued=true;
    requestAnimationFrame(()=>{queued=false;applyLang();});
  });
  ["#sheet","#dayBody","#player","#deepBody",
   "#v-track","#v-gym","#v-food","#v-labs","#v-cal","#v-settings","#v-coach","#v-guide","#v-cycle"
  ].forEach(sel=>{
    const el=$(sel);
    /* characterData as well as childList: the storage report writes its
       lines with textContent, which replaces the text inside an existing node
       rather than adding one, so a childList-only observer never saw it and
       three lines of Settings stayed English on every Spanish load.
       This cannot loop: applyLang caches each node's original text, so a
       second pass computes the same value and writes nothing. */
    if(el)langObs.observe(el,{childList:true,subtree:true,characterData:true});
  });
}
/* Languages offered in the picker. Arabic, Chinese and Russian are held back
   until their guide content is written — a translated interface wrapped around
   English research is worse than staying in English. Add the code here when a
   language is done. */
const LANGON=new Set(["en","es"]);
function langReady(c){return LANGON.has(c);}

/* asked once, then lives in Settings */
function langPop(first){
  // a language appears once its guide content exists; the rest are simply
  // not in the list, with no note about why
  const ready=LANGS.filter(l=>langReady(l.c));
  const row=l=>`<button class="langbtn ${curLang()===l.c?"on":""}" data-lang="${l.c}">
      <span class="lgf">${l.f}</span><span class="lgn">${l.n}</span>
      ${curLang()===l.c?`<span class="lgc">✓</span>`:""}</button>`;
  $("#sheet").innerHTML=`<h3>${first?"Choose your language":"Language"}</h3>
    <div class="msub">${first?"Elige tu idioma":"You can change this any time from the profile menu"}</div>
    <div class="langlist">${ready.map(row).join("")}</div>
    ${first?"":`<button class="ghost" id="lgClose">Close</button>`}`;
  $("#modal").classList.add("on");
  $$("[data-lang]").forEach(b=>b.onclick=()=>{
    S.settings.lang=b.dataset.lang;S.settings.langAsked=true;save();
    closeModal();renderAll();setTab(tab);
  });
  if($("#lgClose"))$("#lgClose").onclick=()=>{S.settings.langAsked=true;save();closeModal();};
}


/* ---------- cycle screen ---------- */
/* A day's marker on the calendar. Sex outranks orgasm, so a day with both
   shows the heart rather than two symbols competing in one cell. */
const SEXACTS=["Protected sex","Unprotected sex","Oral sex","Sex"];
const SOLOACTS=["Orgasm","Masturbation"];
function cycMark(k){
  const d=(cycDayLog(k).drive)||[];
  if(SEXACTS.some(x=>d.indexOf(x)>=0))return "\u2764\ufe0f";
  if(SOLOACTS.some(x=>d.indexOf(x)>=0))return "\ud83d\udca6";
  return "";
}

