function CY(){return CYCT[curLang()]||CYCT.en;}
/* what her own log says about this phase, which beats a generic rule */
function cycOwnPattern(phase){
  if(!phase)return null;
  const c=cycS(),tally={};
  let days=0;
  Object.keys(c.days).forEach(k=>{
    const ph=cycPhase(parseISO(k));
    if(ph!==phase)return;
    days++;
    ["sym","mood","gut"].forEach(g=>{
      (c.days[k][g]||[]).forEach(o=>{if(o!=="Everything is fine")tally[o]=(tally[o]||0)+1;});
    });
  });
  if(days<3)return null;
  const top=Object.keys(tally).sort((a,b)=>tally[b]-tally[a]).slice(0,3)
    .filter(o=>tally[o]>=2);
  return top.length?{days:days,top:top}:null;
}
function cycTrend(grp,opt,win){
  const c=cycS();let n=0;
  for(let i=0;i<win;i++){
    const k=iso(new Date(Date.now()-i*DAY));
    if((c.days[k]||{})[grp]&&c.days[k][grp].indexOf(opt)>=0)n++;
  }
  return n;
}
function cycInsights(){
  const out=[],T=CY();
  const today=new Date(),k=iso(today);
  if(cycSex()==="f"){
    const p=cycPredict(),day=cycDay(today),ph=cycPhase(today);
    if(!p){out.push({lvl:"plain",ic:"📅",t:T.setup});return out;}
    const conf=cycConfidence();
    const PHI={menstrual:"🌙",follicular:"🌱",ovulation:"✨",luteal:"🌗"};
    out.push({lvl:"phase",ic:PHI[ph]||"📅",t:T.day(day,phName(ph)),b:T.phaseW[ph]||""});
    const dl=Math.round((parseISO(p.nextStart).getTime()-parseISO(k).getTime())/DAY);
    out.push({lvl:"plain",ic:"📅",
      t:dl>0?T.nextIn(dl,fmtShort(p.nextStart)):T.nextWas(fmtShort(p.nextStart)),
      b:conf.lvl==="none"?T.confNone
        :conf.lvl==="good"?T.confGood(conf.n+1,p.avg,conf.sp)
        :conf.lvl==="rough"?T.confRough(conf.sp)
        :T.confWide(conf.sp)});
    if(ph!=="menstrual"&&ph!=="ovulation")
      out.push({lvl:"plain",ic:"🥚",t:T.fertH(fmtShort(p.fertileFrom),fmtShort(p.fertileTo)),b:T.fertB});
    const ms=cycMoodStats(60);
    if(ms.swings>0){
      const worst=Object.keys(ms.byPhase).sort((a,b)=>
        (ms.byPhase[b].swings/ms.byPhase[b].days)-(ms.byPhase[a].swings/ms.byPhase[a].days))[0];
      out.push({lvl:"own",ic:"🌊",t:T.swingH,
        b:T.swingB(ms.swings,ms.days,worst?phName(worst).toLowerCase():null)});
    }
    const own=cycOwnPattern(ph);
    out.push(own?{lvl:"own",ic:"📊",t:T.ownH,
                  b:T.ownB(own.days,phName(ph).toLowerCase(),own.top.map(x=>L(x)).join(", "))}
                :{lvl:"plain",ic:"🏋️",t:T.trainH,b:T.trainB});
    if(ph==="menstrual")out.push({lvl:"nutr",ic:"🥗",t:T.eatH,b:T.eatMen});
    if(ph==="luteal")out.push({lvl:"nutr",ic:"🥗",t:T.eatH,b:T.eatLut});
  }else{
    const wood=cycTrend("sym","Morning erection",14),
          nowood=cycTrend("sym","No morning erection",14),
          logged=wood+nowood;
    out.push({lvl:"phase",ic:"📊",t:T.m14,b:logged?T.mWood(wood,logged):T.mNone});
    const tired=cycTrend("sym","Fatigue",14),
          ang=cycTrend("mood","Irritated",14)+cycTrend("mood","Angry",14);
    const ms=cycMoodStats(60);
    if(ms.swings>0)out.push({lvl:"own",ic:"🌊",t:T.swingH,b:T.swingB(ms.swings,ms.days,null)});
    if(tired>=4)out.push({lvl:"own",ic:"🔋",t:T.mTiredH,b:T.mTiredB(tired)});
    if(ang>=4)out.push({lvl:"own",ic:"😠",t:T.mAngH,b:T.mAngB(ang)});
    out.push({lvl:"plain",ic:"🧭",t:T.mWhyH,b:T.mWhyB});
  }
  return out;
}
/* Dates spliced into a sentence never reach tr(), so they format in the
   reader's own locale rather than being translated afterwards. */
const LOCM={en:"en-US",es:"es-ES",ar:"ar",zh:"zh-CN",ru:"ru-RU"};
function curLocale(){return LOCM[curLang()]||"en-US";}
function fmtShort(k){
  const d=parseISO(k);
  return d.toLocaleDateString(curLocale(),{month:"short",day:"numeric"});
}
function renderCycle(){
  const el=$("#v-cycle");
  if(!el)return;
  if(!cycOn()){
    el.innerHTML=`<div class="vsub">Cycle</div>
      <div class="vhead"><h2>Not set up</h2><div class="spacer"></div></div>
      <div class="panel"><div class="stonote">Choose a profile in settings to turn this on.</div></div>`;
    return;
  }
  const f=cycSex()==="f";
  const y=cycDate.getFullYear(),m=cycDate.getMonth();
  const first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),td=iso(new Date());
  let cells="";
  for(let i=0;i<first;i++)cells+=`<div class="cday empty"></div>`;
  for(let d=1;d<=days;d++){
    const k=iso(new Date(y,m,d));
    const cls=[ "cday" ];
    if(k===td)cls.push("today");
    if(f&&cycBleedOn(k))cls.push("bleed");
    else if(f&&cycPredBleedOn(k))cls.push("predbleed");
    else if(f&&cycOvOn(k))cls.push("ov");
    else if(f&&cycFertileOn(k))cls.push("fert");
    const n=cycCount(k),mk=cycMark(k);
    cells+=`<div class="${cls.join(" ")}" data-cyc="${k}"><span class="num">${d}</span>${
      mk?`<span class="cmk">${mk}</span>`:n?`<span class="cdot"></span>`:""}</div>`;
  }
  const ins=cycInsights();
  el.innerHTML=`<div class="vsub">${f?"Cycle and mood":"Rhythm and mood"}</div>
    <div class="vhead"><h2>${f?"My cycle":"My baseline"}</h2><div class="spacer"></div></div>
    <div class="panel">
      <div class="cyctop"><button class="mini" id="cycPrev">‹</button>
        <span class="cycmon">${cycDate.toLocaleDateString(curLocale(),{month:"long",year:"numeric"})}</span>
        <button class="mini" id="cycNext">›</button></div>
      <div class="cycgrid">${["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(d=>`<div class="cdow">${d}</div>`).join("")}${cells}</div>
      ${f?`<div class="cyckey">
        <span><i class="sw bleed"></i>Period</span>
        <span><i class="sw predbleed"></i>Expected</span>
        <span><i class="sw fert"></i>Fertile</span>
        <span><i class="sw ov"></i>Ovulation</span>
        <span>\u2764\ufe0f Sex</span>
        <span>\ud83d\udca6 Orgasm</span></div>`:""}
    </div>
    <button class="primary" id="cycLogBtn">Log today</button>
    ${f?`<button class="ghost" id="cycPerBtn">${cycBleedOn(td)?"Remove period from today":"Period started today"}</button>`:""}
    <div class="inshead"><span class="ih">${f?"Where you are":"How it is going"}</span><i class="il"></i></div>
    ${ins.map(x=>`<div class="cycins ${x.lvl}"><div class="cinh"><span class="cini">${x.ic||""}</span>${x.t}</div>${
      x.b?`<div class="cinb">${x.b}</div>`:""}</div>`).join("")}
    <button class="disclaimer" id="cycDisc">⚠ Not medical advice — tap to read</button>`;
  $("#cycPrev").onclick=()=>{cycDate=new Date(y,m-1,1);renderCycle();};
  $("#cycNext").onclick=()=>{cycDate=new Date(y,m+1,1);renderCycle();};
  $("#cycLogBtn").onclick=()=>cycLogSheet(iso(new Date()));
  if($("#cycPerBtn"))$("#cycPerBtn").onclick=()=>{cycToggleBleed(iso(new Date()));renderCycle();};
  if($("#cycDisc"))$("#cycDisc").onclick=showDisclaimer;
  $$("[data-cyc]",el).forEach(c=>c.onclick=()=>cycLogSheet(c.dataset.cyc));
  if(curLang()!=="en")applyLang();
}
function cycLogSheet(k){
  const f=cycSex()==="f";
  const draw=()=>{
    const groups=cycGroups();
    $("#sheet").innerHTML=`<h3>${parseISO(k).toLocaleDateString(curLocale(),{weekday:"short",month:"short",day:"numeric"})}</h3>
      <div class="msub">${f&&cycDay(parseISO(k))?`Cycle day ${cycDay(parseISO(k))}`:"Tap what applies"}</div>
      ${f?`<button class="ghost cycper" id="cycPer2">${cycBleedOn(k)?"Remove period from this day":"Mark as a period day"}</button>`:""}
      ${groups.map(g=>`<div class="cggrp"><div class="cgh" style="color:${g.c}">${g.n}</div>
        <div class="cgl">${g.o.map(o=>`<button class="cgchip${cycHas(k,g.k,o)?" on":""}" style="--cc:${g.c}"
          data-cg="${g.k}" data-co="${o.replace(/"/g,"&quot;")}"><span class="cge">${cycEmoji(o)}</span><span class="cgt">${o}</span></button>`).join("")}</div></div>`).join("")}
      <button class="primary" id="cgDone">Done</button>`;
    // toggled in place: a full redraw flickers and can swallow a fast second tap
    $$("[data-cg]",$("#sheet")).forEach(b=>b.onclick=()=>{
      cycToggle(k,b.dataset.cg,b.dataset.co,false);
      b.classList.toggle("on",cycHas(k,b.dataset.cg,b.dataset.co));});
    if($("#cycPer2"))$("#cycPer2").onclick=()=>{
      cycToggleBleed(k);draw();
      // the calendar behind the sheet is now stale, and dismissing by the
      // backdrop never reaches the Done handler that used to refresh it
      if(tab==="cycle")renderCycle();};
    $("#cgDone").onclick=()=>{closeModal();renderCycle();};
    if(curLang()!=="en")applyLang();
  };
  draw();
  $("#modal").classList.add("on");
}

/* ---------- coach screen ---------- */
let coachQ="",coachRes=null;
function coachStarters(){
  const t=activeTrack().filter(p=>!p.label);
  const out=[];
  const Q=CQTPL[curLang()]||CQTPL.en;
  if(t.length>=2)out.push(Q.both(t[0].name,t[1].name));
  if(t.length)out.push(Q.blood(t[0].name));
  if(t.length)out.push(Q.working(t[0].name));
  if(t.length>1)out.push(Q.when(t[1].name));
  out.push(Q.gear);
  out.push(Q.miss);
  if(t.length)out.push(Q.eat(t[t.length-1].name));
  out.push(Q.tired);
  return out.slice(0,6);
}
function renderCoach(){
  const el=$("#v-coach");
  el.innerHTML=`<div class="vsub">Ask the guides</div>
    <div class="vhead"><h2>Coach</h2><div class="spacer"></div></div>
    <div class="askbox">
      <input id="askIn" class="askin" placeholder="Ask about your protocol…" autocomplete="off" value="${coachQ.replace(/"/g,"&quot;")}">
      <button class="askgo" id="askGo" aria-label="Ask">→</button>
    </div>
    <div class="asknote">Answers come from the ${Object.keys(GUIDES).length} guides in this app and your own logged data.
      Nothing is generated and nothing leaves your phone, so it cannot invent a study or a dose — every answer shows where it came from.</div>
    ${coachRes?coachCard(coachRes):`
      <div class="starthead">Try one of these</div>
      <div class="startgrid">${coachStarters().map(q=>`<button class="startq" data-q="${q.replace(/"/g,"&quot;")}">${q}</button>`).join("")}</div>`}
    <button class="disclaimer" id="cDisc">⚠ Not medical advice — tap to read</button>`;
  const go=()=>{coachQ=$("#askIn",el).value.trim();
    coachRes=coachQ?coachAnswer(coachQ):null;renderCoach();};
  $("#askGo",el).onclick=go;
  $("#askIn",el).onkeydown=e=>{if(e.key==="Enter")go();};
  $$("[data-q]",el).forEach(b=>b.onclick=()=>{coachQ=b.dataset.q;coachRes=coachAnswer(coachQ);renderCoach();});
  $$("[data-cgo]",el).forEach(b=>b.onclick=()=>{
    const p=pepFor(b.dataset.cgo);
    refDive(b.dataset.cgo);});
  $("#cDisc",el).onclick=showDisclaimer;
  if($("#ansMore",el))$("#ansMore",el).onclick=()=>{
    coachRes.moreOpen=!coachRes.moreOpen;renderCoach();};
  if($("#ansGear",el))$("#ansGear",el).onclick=gearOverview;
  if($("#askAgain",el))$("#askAgain",el).onclick=()=>{coachQ="";coachRes=null;renderCoach();};
  // built after applyLang has been round, so it applies the language itself
  if(typeof applyLang==="function")applyLang();
}
function coachCard(r){
  const more=r.more||[],open=!!r.moreOpen;
  const blocks=open?r.blocks.concat(more):r.blocks;
  return `<div class="ansbox">
    <div class="anshead">${r.title}</div>
    ${blocks.map(b=>`<div class="ansb ${b.kind}">${b.text}</div>`).join("")}
    ${more.length?`<button class="ansmore" id="ansMore">${open?CT().less:CT().more(more.length)}</button>`:""}
    ${r.sources.length?`<div class="anssrc"><span class="asl">Read the full guide</span>
      ${r.sources.map(k=>`<button class="asrc" data-cgo="${k}">${guideName(k)} ›</button>`).join("")}</div>`:""}
  </div>
  <button class="ghost" id="askAgain">Ask something else</button>`;
}

/* ============ nav / shell ============ */
const SUBS={track:"Today",guide:"Stack",cycle:"Cycle",labs:"Bloodwork",gym:"Recovery",food:"Food",coach:"Coach",settings:"Settings"};
let tab="track";
/* body.sex is the one with a default and the one the macro calculator sets;
   the cycle setup is the fallback for someone who only used that screen */
function userSex(){
  const b=(S.body&&S.body.sex)||"",c=(S.cycle&&S.cycle.sex)||"";
  return (b==="f"||(!b&&c==="f"))?"f":"m";
}
/* probed once per file per session: absent art is a fallback, not an error */
const _bgSeen={};
function setBg(t){
  const bg=$("#bgimg");if(!bg)return;
  const names=userSex()==="f"?["bg-"+t+"-f.webp","bg-"+t+".webp"]
                             :["bg-"+t+".webp"];
  (function tryAt(i){
    if(i>=names.length){bg.classList.remove("on");
      document.documentElement.classList.remove("hasbg");return;}
    const url=names[i];
    if(_bgSeen[url]===false)return tryAt(i+1);
    const paint=()=>{bg.style.backgroundImage=
      `linear-gradient(rgba(11,18,17,.20),rgba(11,18,17,.50)),url("${url}")`;
      bg.classList.add("on");
      document.documentElement.classList.add("hasbg");};
    if(_bgSeen[url])return paint();
    const im=new Image();
    im.onload=()=>{_bgSeen[url]=true;paint();};
    im.onerror=()=>{_bgSeen[url]=false;tryAt(i+1);};
    im.src=url;
  })(0);
}
function setTab(t){tab=t;setBg(t);$$(".view").forEach(v=>v.classList.remove("on"));$("#v-"+t).classList.add("on");
  $$("#nav button").forEach(b=>b.classList.toggle("on",b.dataset.tab===t));
  $("#bloodBtn").classList.toggle("on",t==="labs");
  if($("#cycBtn"))$("#cycBtn").classList.toggle("on",t==="cycle");
  // "add peptide" belongs on Peps, where the list actually lives
  $("#topSub").textContent=SUBS[t]||"";
  $("#fab").style.display=t==="guide"?"grid":"none";
  ({track:renderTrack,guide:renderGuide,labs:renderLabs,gym:renderGym,food:renderFood,coach:renderCoach,cycle:renderCycle,settings:renderSettings}[t]||(()=>{}))();
  applyLang();
  window.scrollTo({top:0,behavior:"smooth"});}
$$("#nav button").forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
$("#profileBtn").onclick=()=>quickSet();
$("#bloodBtn").onclick=()=>setTab("labs");
$("#cycBtn").onclick=()=>setTab("cycle");
/* the icon only exists for someone who has chosen a profile */
function syncCycBtn(){const b=$("#cycBtn");if(b)b.style.display=cycOn()?"grid":"none";}
/* Shown on Today until a profile is picked or the card is dismissed. Without
   this the tracker is only reachable by opening a menu and reading a list. */
function cycSetupCard(){
  const c=cycS();
  if(c.sex||c.skip)return "";
  const T=CYCS();
  return `<div class="cycsetup">
    <div class="csh">${T.h}</div>
    <div class="csb">${T.b}</div>
    <div class="csbtns">
      <button class="csb1 notr" data-cysetup="f">${CYCL().f}</button>
      <button class="csb1 notr" data-cysetup="m">${CYCL().m}</button>
      <button class="csskip" data-cysetup="skip">${T.no}</button>
    </div></div>`;
}
const CYCSL={
 en:{h:"Cycle and mood tracking",
     b:"Periods, ovulation, mood and symptoms, tracked alongside what you are running. Men get the same thing without the cycle. Off until you choose.",
     no:"Not now"},
 es:{h:"Seguimiento del ciclo y el \u00e1nimo",
     b:"Periodos, ovulaci\u00f3n, \u00e1nimo y s\u00edntomas, junto a lo que est\u00e1s usando. Los hombres tienen lo mismo sin el ciclo. Apagado hasta que elijas.",
     no:"Ahora no"}};
function CYCS(){return CYCSL[curLang()]||CYCSL.en;}
/* Everything you might want to flip lives here rather than being spread
   between the top bar and the bottom of the settings screen. */
/* "Light" is already the workout-intensity label, so these two cannot come
   from the shared dictionary */
const THEMEL={en:{d:"Dark",l:"Light"},es:{d:"Oscuro",l:"Claro"}};
const CYCLBL={en:{f:"Female",m:"Male"},es:{f:"Mujer",m:"Hombre"}};
function CYCL(){return CYCLBL[curLang()]||CYCLBL.en;}
function quickSet(){
  const dark=(S.settings.theme||"dark")==="dark";
  const TH=THEMEL[curLang()]||THEMEL.en;
  const L=LANGS.find(x=>x.c===curLang())||LANGS[0];
  const tog=(id,on)=>`<div class="toggle ${on?"on":""}" id="${id}"></div>`;
  $("#sheet").innerHTML=`<h3>Quick settings</h3>
    <div class="qsrow"><span class="qsl">Appearance</span>
      <div class="qsseg notr">
        <button class="qsb ${dark?"on":""}" data-qstheme="dark">${TH.d}</button>
        <button class="qsb ${dark?"":"on"}" data-qstheme="light">${TH.l}</button>
      </div></div>
    <button class="qsrow qsgo" id="qsLang"><span class="qsl">Language</span>
      <span class="qsv">${L.f} ${L.n}</span><i class="ddchev">\u203a</i></button>
    <div class="qsrow"><span class="qsl">Restock notifications</span>${tog("qsNotif",!!S.settings.notify)}</div>
    <div class="qsrow"><span class="qsl">Daily dose reminder</span>${tog("qsRemind",!!S.settings.remind)}</div>
    <div class="qsrow"><span class="qsl">Cycle tracking</span>
      <div class="qsseg notr">
        <button class="qsb ${cycSex()===""?"on":""}" data-qsex="">Off</button>
        <button class="qsb ${cycSex()==="f"?"on":""}" data-qsex="f">${CYCL().f}</button>
        <button class="qsb ${cycSex()==="m"?"on":""}" data-qsex="m">${CYCL().m}</button>
      </div></div>
    <button class="qsrow qsgo" id="qsAll"><span class="qsl">All settings</span><i class="ddchev">\u203a</i></button>
    <button class="ghost" id="qsClose">Close</button>`;
  $("#modal").classList.add("on");
  // scoped to the sheet: applyTheme() puts data-theme on <html>, and a
  // document-wide lookup here bound this handler to the root element
  $$("[data-qstheme]",$("#sheet")).forEach(b=>b.onclick=()=>{
    S.settings.theme=b.dataset.qstheme;applyTheme();save();quickSet();});
  $("#qsLang").onclick=()=>langPop(false);
  $("#qsNotif").onclick=()=>{S.settings.notify=!S.settings.notify;save();quickSet();};
  $("#qsRemind").onclick=async()=>{
    if(!S.settings.remind){const r=await askNotify();if(!r)return;}
    S.settings.remind=!S.settings.remind;save();updateBadge();quickSet();};
  $$("[data-qsex]",$("#sheet")).forEach(b=>b.onclick=()=>{
    cycS().sex=b.dataset.qsex;save();syncCycBtn();
    if(!cycOn()&&tab==="cycle")setTab("track");
    quickSet();});
  $("#qsAll").onclick=()=>{closeModal();setTab("settings");};
  $("#qsClose").onclick=closeModal;
  if(curLang()!=="en")applyLang();
}
function closeModal(){$("#modal").classList.remove("on");}
$("#modal").onclick=e=>{if(e.target.id==="modal"&&!gateUp)closeModal();};
$("#dayOverlay").onclick=e=>{if(e.target.id==="dayOverlay")closeDay();};
/* How much of this exists nowhere else. Counted in things the user
   recognises, not bytes. */
function dataAtRisk(){
  return Object.keys(S.log||{}).length+(S.workouts||[]).length
        +(S.meals||[]).length+(S.weights||[]).length
        +Object.keys(S.labs||{}).length;
}
function backupGuard(){
  const el=$("#bguard");if(!el)return;
  const nav=$("#nav");
  if(nav)document.documentElement.style.setProperty(
    "--navh",Math.round(nav.getBoundingClientRect().height)+"px");
  const n=dataAtRisk(),age=backupAge();
  const never=age==null,stale=age!=null&&age>=7;
  const snoozed=(S.settings.bgSnooze||0)>Date.now();
  /* nothing worth losing yet, or there is a recent copy, or a stale one was
     put off — a warning that is always up is a warning nobody reads */
  if(n<3||(!never&&!stale)||(stale&&snoozed)){
    el.classList.remove("on");el.innerHTML="";return;}
  const days=Object.keys(S.log||{}).length;
  el.innerHTML=`<div class="bgt">${never?L("Nothing here is backed up"):L("Your backup is out of date")}</div>
    <div class="bgs">${days} ${L("days logged, stored only on this device.")}
      ${never?L("Deleting the home screen icon erases all of it."):`${L("Last saved")} ${age} ${L("days ago.")}`}</div>
    <div class="bgr"><button class="bgb" id="bgSave">${L("Save a backup")}</button>
    ${never?"":`<button class="bgx" id="bgLater">${L("Later")}</button>`}</div>`;
  el.classList.add("on");
  $("#bgSave").onclick=async()=>{await exportData();save();backupGuard();};
  const lt=$("#bgLater");
  if(lt)lt.onclick=()=>{S.settings.bgSnooze=Date.now()+3*DAY;save();backupGuard();};
}
function renderAll(){renderTrack();backupGuard();}
let tT;function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("on");clearTimeout(tT);tT=setTimeout(()=>t.classList.remove("on"),1900);}

/* tooltips: hover on desktop, press-and-hold on touch */
let tipEl;
function showTipFor(el){hideTip();const r=el.getBoundingClientRect();tipEl=document.createElement("div");tipEl.className="tip2";tipEl.textContent=el.dataset.tip;document.body.appendChild(tipEl);tipEl.style.left=(r.left+r.width/2)+"px";tipEl.style.top=(r.top-6)+"px";}
function hideTip(){if(tipEl){tipEl.remove();tipEl=null;}}
function initTips(){
  document.addEventListener("mouseover",e=>{const t=e.target.closest("[data-tip]");if(t)showTipFor(t);});
  document.addEventListener("mouseout",e=>{if(e.target.closest("[data-tip]"))hideTip();});
  document.addEventListener("touchstart",e=>{const t=e.target.closest("[data-tip]");if(t){t._held=false;t._timer=setTimeout(()=>{t._held=true;showTipFor(t);},350);}},{passive:true});
  document.addEventListener("touchend",e=>{const t=e.target.closest("[data-tip]");if(t){clearTimeout(t._timer);if(t._held){e.preventDefault();setTimeout(hideTip,1000);}}},{passive:false});
}

/* add-to-home-screen hint for iOS Safari (Android's own install is already simple) */
function standalone(){return matchMedia("(display-mode: standalone)").matches||navigator.standalone===true;}
function showInstall(){
  const bar=$("#installBar");if(!bar||standalone()||localStorage.getItem("vb_install_x"))return;
  if(!/iphone|ipad|ipod/i.test(navigator.userAgent))return;
  bar.innerHTML=`<div class="it">To install: tap <b>Share</b> ⬆ at the bottom of Safari, then <b>Add to Home Screen</b>.</div><button class="bx" id="instX" aria-label="Dismiss">×</button>`;
  bar.classList.add("on");
  $("#instX").onclick=()=>{bar.classList.remove("on");localStorage.setItem("vb_install_x","1");};
}

/* public build (hosted for others) hides the Sales / resale business tab */
const PUBLIC=!!window.VIALBACK_PUBLIC;


/* init */
$("#deepClose").onclick=closeDeep;
$("#gearView").onclick=e=>{if(e.target.id==="gearView")closeGear();};
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#deepView").classList.contains("on"))closeDeep();});
if(!S.foods.length&&S.meals.length){const seen={};
  S.meals.forEach(m=>{const k=foodKey(m.name);if(!seen[k]){seen[k]=1;saveFoodItem(m);}});save();}
applyLabRanges();initTips();renderTrack();syncNative();applyLang();watchLang();syncCycBtn();
/* repair any period list fragmented by the old edit behaviour */
if(cycS().periods.length){const before=JSON.stringify(cycS().periods);
  if(JSON.stringify(cycNormalise())!==before)save();}
initSW();startReminderLoop();setBg(tab);
/* the one thing that has to be seen before anything else */
setTimeout(supervisionGate,700);
/* If localStorage came back empty, something cleared it — pull the data back
   from the mirror before the user starts typing over a blank app. Then ask the
   browser not to do it again. */
(async()=>{
  const msg=await recoverState();
  if(msg){
    try{S=Object.assign(S,JSON.parse(localStorage.getItem(KEY)||"{}"));}catch(e){}
    renderAll();
    setTimeout(()=>toast(msg),400);
  }
  const p=await askPersist();
  if(p===false&&!S.settings.persistAsked){
    S.settings.persistAsked=true;save();
    setTimeout(()=>toast("Add The Lab to your home screen so the browser stops clearing your data"),1600);
  }
})();
if(!S.settings.langAsked)setTimeout(()=>langPop(true),450);
if(PUBLIC)setTimeout(showInstall,1400);
